/* ============ mega.js — Mega Stones and Mega Evolution (MrSurvivor fork) ============
 * In every run (since 21-10-2026; fork/LAB.md tried it first), and the menu's "puede megaevolucionar" (Can Mega Evolve) too.
 * When you beat a rift's legendary, if your Pokémon can Mega Evolve (it has a
 * Mega sprite in SpriteCollab: G.MEGA_FORMS, js/fork/mega-sprites.js, generated by
 * fork/fetch-megas.py) and you aren't holding it already, from minute 5 of the run there's
 * a 1 in 30 chance it offers you its MEGA STONE (DROP_T, DROP_P). It's a holdable
 * item like the others (one per run): if you were holding another, you choose.
 * While you hold it your Pokémon is Mega Evolved:
 *   - the Mega's sprite (and its shiny, if there is one)
 *   - +25 % damage, +10 % speed, +15 % max HP and +8 % defense
 *   - the Mega's type when it changes (TYPES); if not, the same one
 * If you swap it for another item, it goes back to how it was.
 * Co-op: { k:'mega', u, on } to the host, who passes it on; everyone sees your Mega.
 * Hooks: Rift won (riftWon), G.Game.offerItem; G.Admin.repaint draws the look.
 * Test: fork/test-lab.cjs (solo) and fork/test-gameplay.cjs,
 * and fork/test-lab-coop.cjs (group).
 */
G.Mega = (() => {
  // Megas that change type (the rest keep the Pokémon's).
  const TYPES = { 6: ['fire', 'dragon'], 334: ['dragon', 'fairy'], 383: ['ground', 'fire'], 428: ['normal', 'fighting'] };
  const ATK = 1.25, SPD = 1.1, HP = 0.15, DEF = 0.08;
  const DROP_T = 300, DROP_P = 1 / 30;   // the stone: from minute 5, 1 in 30 per rift won
  const NAME = 'Megapiedra', DESC = 'Tu Pokémon megaevoluciona mientras la lleve: +25 % de daño, +10 % de velocidad, +15 % de vida y +8 % de defensa.';
  const SAY = '¡Megaevolución!', SAY_PRIMAL = '¡Regresión primigenia!';
  const CAN = 'Puede megaevolucionar', HINT = 'Puede megaevolucionar: desde el minuto 5, cada legendario de grieta que venzas con él tiene 1 entre 30 de soltar su Megapiedra.';
  // Columns: Spanish, English, French, Italian, Portuguese (Brazil), Simplified and Traditional Chinese.
  const ROWS = [
    [NAME, 'Mega Stone', 'Méga-Gemme', 'Megapietra', 'Mega Pedra', '超级石', '超級石'],
    [DESC, 'Your Pokémon Mega Evolves while holding it: +25% damage, +10% speed, +15% HP and +8% defense.',
     'Ton Pokémon méga-évolue tant qu’il la tient : +25 % de dégâts, +10 % de vitesse, +15 % de PV et +8 % de défense.',
     'Il tuo Pokémon megaevolve finché la tiene: +25% di danni, +10% di velocità, +15% di PS e +8% di difesa.',
     'Seu Pokémon megaevolui enquanto a segura: +25% de dano, +10% de velocidade, +15% de PS e +8% de defesa.',
     '携带时你的宝可梦会超级进化：伤害+25%，速度+10%，HP+15%，防御+8%。',
     '攜帶時你的寶可夢會超級進化：傷害+25%，速度+10%，HP+15%，防禦+8%。'],
    [SAY, 'Mega Evolution!', 'Méga-Évolution !', 'Megaevoluzione!', 'Megaevolução!', '超级进化！', '超級進化！'],
    [SAY_PRIMAL, 'Primal Reversion!', 'Primo-Résurgence !', 'Archeorisveglio!', 'Reversão Primitiva!', '原始回归！', '原始回歸！'],
    [CAN, 'Can Mega Evolve', 'Peut méga-évoluer', 'Può megaevolversi', 'Pode megaevoluir', '可以超级进化', '可以超級進化'],
    [HINT, 'Can Mega Evolve: from minute 5 on, each rift legendary you defeat with it has a 1 in 30 chance to drop this Pokémon\'s Mega Stone.',
     'Peut méga-évoluer : dès la 5e minute, chaque légendaire de faille vaincu avec lui a 1 chance sur 30 de lâcher sa Méga-Gemme.',
     'Può megaevolversi: dal 5º minuto, ogni leggendario di fenditura sconfitto con lui ha 1 probabilità su 30 di lasciare la sua Megapietra.',
     'Pode megaevoluir: a partir do minuto 5, cada lendário de fenda derrotado com ele tem 1 chance em 30 de deixar sua Mega Pedra.',
     '可以超级进化：第5分钟起，带它击败的每只裂缝传说宝可梦都有1/30的几率掉落它的超级石。',
     '可以超級進化：第5分鐘起，帶它擊敗的每隻裂縫傳說寶可夢都有1/30的機率掉落它的超級石。']
  ];
  ['en', 'fr', 'it', 'pt-BR', 'zh-Hans', 'zh-Hant'].forEach((l, i) => G.I18n.add(Object.fromEntries(ROWS.map(r => [r[0], r[i + 1]])), l));

  /** Does it have a Mega (with a sprite)? */
  const can = dex => !!(G.MEGA_FORMS && G.MEGA_FORMS[dex] && G.SPRITE_META['m' + dex]);

  // "Puede megaevolucionar" (Can Mega Evolve), outside the run (js/ui/menu.js; styles in css/brand.css):
  // the Mega Stone on its collection tile, a chip on the menu's partner and a
  // line on its card saying how to get it. Empty if it has no Mega.
  const shown = dex => can(dex);
  const stone = (size = 14) => G.Icons.html('megastone', size);
  const badge = dex => shown(dex) ? `<span class="mega-badge" title="${CAN}">${stone(18)}</span>` : '';
  const chip = dex => shown(dex) ? `<span class="mega-chip" title="${CAN}">${stone()} Mega</span>` : '';
  const hint = dex => shown(dex) ? `<p class="mega-hint">${stone()} ${HINT}</p>` : '';

  // Icon: a blue sphere with the double helix.
  G.Icons.UI.megastone = { pal: { b: '#4fb4ff', d: '#2a6fb0', w: '#e6f4ff', y: '#ffd23f', r: '#ff5f6d' }, rows: [
    '....kkkk....', '..kkbbbbkk..', '.kwbbbyrbdk.', '.kwbbyrbbdk.', 'kbbbyrbbbbdk', 'kbbbbrybbbdk',
    'kbbbbbrybbdk', 'kbbbbyrbbbdk', '.kbbyrbbbdk.', '.kbbbbbbddk.', '..kkddddkk..', '....kkkk....'] };

  // Holdable item (not in G.Items.LIST: it doesn't come from chests, only from rifts).
  G.Items.BY.megastone = { id: 'megastone', name: NAME, desc: DESC, on: p => evolve(p), off: p => revert(p) };

  // ---------------- Mega Evolution ----------------

  /** Your Pokémon Mega Evolves (when it takes the stone). */
  function evolve(p) {
    if (p.mega || !can(p.dex)) return;
    const hp = Math.round(p.maxHp * HP);
    p.mega = { mon: p.mon, hp };
    if (TYPES[p.dex]) p.mon = Object.assign({}, p.mon, { types: TYPES[p.dex] });
    p.atkMul *= ATK; p.spdMul *= SPD; p.dmgReduce += DEF;
    p.addMaxHp(hp);
    look(p, true);
    G.FX.ring(p.x, p.y, 8, 150, '#ff8ad8', 0.9, 6);
    G.FX.burst(p.x, p.y - p.bodyH * 0.5, '#ffd3f1', 60, 280);
    G.Audio.sfx('legend');
    G.Camera.kick(0.6);
    G.Spawner.say(G.MEGA_FORMS[p.dex] === 'Primal' ? SAY_PRIMAL : SAY, 2.8, true);
    share(true);
  }

  /** Goes back to how it was (when the stone comes off). */
  function revert(p) {
    if (!p.mega) return;
    p.mon = p.mega.mon;
    p.atkMul /= ATK; p.spdMul /= SPD; p.dmgReduce -= DEF;
    p.maxHp -= p.mega.hp; p.hp = Math.min(p.hp, p.maxHp);
    p.mega = null;
    look(p, false);
    share(false);
  }

  /** The Mega's sprite or the usual one (on your Pokémon or on a teammate's puppet). */
  function look(p, on) {
    p.megaKey = on ? 'm' + p.dex : null;
    if (on) G.Sprites.preload([p.megaKey], 8000, p.shiny);
    G.Admin.repaint(p);
  }

  // ---------------- co-op ----------------

  function share(on) {
    if (!G.Coop.active) return;
    const msg = { k: 'mega', u: G.Net.uid, on };
    if (G.Coop.isHost) { for (const m of G.Coop.mates) if (m.connected) G.Net.send(m.uid, msg); }
    else G.Net.toHost(msg);
  }

  G.Net.on((from, msg) => {
    if (!msg || msg.k !== 'mega' || !G.Coop.active || typeof msg.on !== 'boolean') return;
    // The host only accepts what each player sends about themselves, and passes it on; a guest, only what the host sends.
    if (G.Coop.isHost) {
      if (msg.u !== from) return;
      for (const m of G.Coop.mates) if (m.connected && m.uid !== from) G.Net.send(m.uid, msg);
    } else if (from !== G.Net.hostUid) return;
    const m = G.Coop.mate(msg.u);
    if (m && m.pl && can(m.pl.dex)) look(m.pl, msg.on);
  });

  // ---------------- the stone, on winning a rift ----------------

  let pending = false;
  /** Rift won: if your Pokémon can Mega Evolve and you aren't holding it, from minute 5 and with a 1 in 30 chance, its stone. */
  function riftWon(pl) {
    if (can(pl.dex) && pl.item !== 'megastone' && G.Game.st.time >= DROP_T && Math.random() < DROP_P) pending = true;
  }
  // It's offered back on the map, with no other screen in front (bond, cards...).
  setInterval(() => {
    if (!pending || !G.Game) return;               // (G.Game: dev.html may still be loading js/game.js)
    const pl = G.Game.player;
    if (!pl || G.Game.state === 'ui' || G.Game.state === 'over') { pending = false; return; }
    if (G.Game.state !== 'playing' || G.Rift.inArena || pl.dead) return;
    if (['scr-bond', 'scr-item', 'scr-levelup', 'scr-pause'].some(G.UI.isOpen)) return;
    pending = false;
    G.Game.offerItem('megastone');
  }, 250);

  return { can, riftWon, TYPES, DROP_T, DROP_P, badge, chip, hint };
})();
